//! Whether the committed generated files are current (SPEC.md §9.4), checked
//! by `cargo xtask check-freshness` in the initial honesty job, without Lean
//! and in seconds. A change to a source, a project file, a lock, or the
//! compiler that was committed without regenerating what depends on it fails
//! here, before the expensive roots of the gate start, instead of hours into
//! them. It adds a precondition to the gate and replaces none of its checks:
//! `golden`, `examples`, and the bootstrap and production-export cases still
//! compare every generated byte.
//!
//! What it reads: each committed build oracle `expected/build/manifest.json`
//! records the digest and length of every input its build read and the
//! compiler semantics that built it; each committed package of
//! `tests/production-export/` records, in `provenance.json`, the compiler
//! semantics and the semantic ID of the build it was exported from; each
//! project's `lexlean.lock` is what `lexlean lock --check` accepts.

use std::collections::BTreeMap;

use camino::{Utf8Path, Utf8PathBuf};
use lexlean::{Engine, LockRequest};
use serde_json::Value;
use sha2::{Digest, Sha256};

/// The projects of `tests/production-export/`, each with its directory.
pub const EXPORTED: [(&str, &str); 5] = [
    ("bootstrap", "bootstrap"),
    ("helpdesk", "examples/helpdesk"),
    ("production", "examples/production"),
    ("production-coverage", "examples/production-coverage"),
    ("stdlib", "stdlib"),
];

/// What the check read.
#[derive(Debug, Default, Clone, PartialEq, Eq)]
pub struct Summary {
    /// Projects with a committed build oracle.
    pub projects: usize,
    /// Recorded inputs hashed.
    pub inputs: usize,
    /// Committed export packages read.
    pub packages: usize,
}

fn sha256_hex(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

fn read_json(path: &Utf8Path) -> Result<Value, String> {
    let bytes = std::fs::read(path.as_std_path()).map_err(|error| format!("{path}: {error}"))?;
    serde_json::from_slice(&bytes).map_err(|error| format!("{path}: {error}"))
}

/// Every project directory under `root` with a committed build oracle.
#[must_use]
pub fn oracle_projects(root: &Utf8Path) -> Vec<Utf8PathBuf> {
    let mut found = Vec::new();
    for parent in [root.to_owned(), root.join("examples")] {
        let Ok(entries) = std::fs::read_dir(parent.as_std_path()) else {
            continue;
        };
        for entry in entries.flatten() {
            let Ok(path) = Utf8PathBuf::from_path_buf(entry.path()) else {
                continue;
            };
            if path.join("expected/build/manifest.json").is_file() {
                found.push(path);
            }
        }
    }
    found.sort();
    found
}

/// The source packages a project names, by package, as directories.
fn source_packages(
    root: &Utf8Path,
    project: &Utf8Path,
) -> Result<BTreeMap<String, Utf8PathBuf>, String> {
    let file = project.join("lexlean.toml");
    let text =
        std::fs::read_to_string(file.as_std_path()).map_err(|error| format!("{file}: {error}"))?;
    let config: toml::Value = toml::from_str(&text).map_err(|error| format!("{file}: {error}"))?;
    let mut packages = BTreeMap::new();
    for row in config
        .get("source_package")
        .and_then(toml::Value::as_array)
        .into_iter()
        .flatten()
    {
        if let (Some(name), Some(path)) = (
            row.get("package").and_then(toml::Value::as_str),
            row.get("path").and_then(toml::Value::as_str),
        ) {
            packages.insert(name.to_owned(), root.join(path));
        }
    }
    Ok(packages)
}

/// Whether one project's committed build oracle and lock are current. Returns
/// the oracle's semantic ID and the number of inputs hashed.
///
/// # Errors
///
/// Every stale or unreadable input, one per line.
pub fn check_project(root: &Utf8Path, project: &Utf8Path) -> Result<(String, usize), String> {
    let mut unmet = Vec::new();
    let manifest = read_json(&project.join("expected/build/manifest.json"))?;
    let name = project.strip_prefix(root).unwrap_or(project);
    let language = manifest["language"].as_str().unwrap_or_default();
    let compiler = lexlean::compiler_semantics_id_for(language).to_hex();
    if manifest["compiler"]["semantics_id"].as_str() != Some(compiler.as_str()) {
        unmet.push(format!(
            "{name}: expected/build was built by compiler semantics {}, this compiler is {compiler}",
            manifest["compiler"]["semantics_id"]
        ));
    }
    let packages = source_packages(root, project)?;
    let mut hashed = 0;
    for input in manifest["inputs"].as_array().into_iter().flatten() {
        let path = input["path"].as_str().unwrap_or_default();
        if input["kind"] == "lexicon" {
            // A lexicon's digest is its package tree's: the lock records a
            // local package's (`lock --check` below), and the compiler's
            // semantics ID, compared above, covers an embedded one.
            continue;
        }
        let file = match path.split_once(':') {
            Some((package, relative)) => match packages.get(package) {
                Some(directory) => directory.join(relative),
                None => {
                    unmet.push(format!(
                        "{name}: input `{path}` names no source package of lexlean.toml"
                    ));
                    continue;
                }
            },
            None => project.join(path),
        };
        hashed += 1;
        match std::fs::read(file.as_std_path()) {
            Ok(bytes) => {
                if input["sha256"].as_str() != Some(sha256_hex(&bytes).as_str())
                    || input["byte_length"].as_u64() != Some(bytes.len() as u64)
                {
                    unmet.push(format!(
                        "{name}: `{path}` changed since expected/build was generated"
                    ));
                }
            }
            Err(error) => unmet.push(format!("{name}: `{path}`: {error}")),
        }
    }
    let lock = Engine::load(&project.join("lexlean.toml")).and_then(|engine| {
        engine.lock(LockRequest {
            check_only: true,
            allow_network: false,
        })
    });
    if let Err(error) = lock {
        unmet.push(format!(
            "{name}: `lexlean lock --check` fails: {:?}",
            error
                .diagnostics
                .iter()
                .map(|diagnostic| diagnostic.message.clone())
                .collect::<Vec<_>>()
        ));
    }
    if unmet.is_empty() {
        Ok((
            manifest["semantic_id"]
                .as_str()
                .unwrap_or_default()
                .to_owned(),
            hashed,
        ))
    } else {
        Err(unmet.join("\n"))
    }
}

/// Whether every committed generated file under `root` is current.
///
/// # Errors
///
/// Every stale file, one per line, with the regeneration that renews it.
pub fn check(root: &Utf8Path) -> Result<Summary, String> {
    let mut unmet = Vec::new();
    let mut summary = Summary::default();
    let mut semantic = BTreeMap::new();
    for project in oracle_projects(root) {
        summary.projects += 1;
        match check_project(root, &project) {
            Ok((id, hashed)) => {
                summary.inputs += hashed;
                semantic.insert(project, id);
            }
            Err(reason) => unmet.push(reason),
        }
    }
    let compiler = lexlean::compiler_semantics_id_for(lexlean::LANGUAGE_1_2).to_hex();
    for (exported, directory) in EXPORTED {
        let packages = root
            .join("tests/production-export")
            .join(exported)
            .join("packages");
        let expected = semantic.get(&root.join(directory));
        for entry in walkdir::WalkDir::new(packages.as_std_path())
            .into_iter()
            .flatten()
        {
            if entry.file_name() != "provenance.json" {
                continue;
            }
            let Ok(path) = Utf8PathBuf::from_path_buf(entry.into_path()) else {
                continue;
            };
            summary.packages += 1;
            let relative = path.strip_prefix(root).unwrap_or(&path).to_owned();
            let provenance = match read_json(&path) {
                Ok(value) => value,
                Err(reason) => {
                    unmet.push(reason);
                    continue;
                }
            };
            if provenance["compiler_semantics"].as_str() != Some(compiler.as_str()) {
                unmet.push(format!(
                    "{relative}: exported by compiler semantics {}, this compiler is {compiler}",
                    provenance["compiler_semantics"]
                ));
            }
            let sources: Vec<&str> = provenance["sources"]
                .as_array()
                .into_iter()
                .flatten()
                .filter_map(Value::as_str)
                .collect();
            if expected.is_none_or(|id| sources != [id.as_str()]) {
                unmet.push(format!(
                    "{relative}: exported from {sources:?}, {directory}/expected/build is {}",
                    expected.map_or("missing", String::as_str)
                ));
            }
        }
    }
    if unmet.is_empty() {
        Ok(summary)
    } else {
        unmet.sort();
        Err(format!(
            "{} committed generated file(s) are stale; regenerate them (`regenerate.yml`, or the `-write` recipes):\n{}",
            unmet.len(),
            unmet.join("\n")
        ))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn copy(from: &Utf8Path, to: &Utf8Path) {
        for entry in walkdir::WalkDir::new(from.as_std_path())
            .into_iter()
            .flatten()
        {
            let relative = entry
                .path()
                .strip_prefix(from.as_std_path())
                .expect("below");
            if relative.starts_with(".lexlean") {
                continue;
            }
            let target = to.as_std_path().join(relative);
            if entry.file_type().is_dir() {
                std::fs::create_dir_all(&target).expect("dir");
            } else if entry.file_type().is_file() {
                std::fs::copy(entry.path(), &target).expect("copy");
            }
        }
    }

    #[test]
    fn a_committed_oracle_is_current_and_a_changed_input_is_stale() {
        let root = crate::support::repo_root();
        let temp = tempfile::tempdir().expect("tempdir");
        let copy_root = Utf8PathBuf::from_path_buf(temp.path().to_owned()).expect("utf8");
        let project = copy_root.join("examples/nat-add-zero");
        copy(&root.join("examples/nat-add-zero"), &project);
        let (semantic, hashed) =
            check_project(&copy_root, &project).expect("the committed oracle is current");
        assert!(!semantic.is_empty() && hashed >= 2, "{semantic} {hashed}");
        let source = walkdir::WalkDir::new(project.join("src").as_std_path())
            .into_iter()
            .flatten()
            .find(|entry| entry.path().extension().is_some_and(|ext| ext == "tex"))
            .expect("a source")
            .into_path();
        let mut text = std::fs::read_to_string(&source).expect("source");
        text.push('\n');
        std::fs::write(&source, text).expect("write");
        let stale = check_project(&copy_root, &project).expect_err("a changed source is stale");
        assert!(
            stale.contains("changed since expected/build was generated"),
            "{stale}"
        );
        std::fs::remove_file(project.join("expected/build/manifest.json")).expect("remove");
        assert!(
            check_project(&copy_root, &project).is_err(),
            "a missing oracle fails"
        );
    }
}
